/* @autogenerated */
import {
  TEMPLATE_EXCEL_COLUMNS,
  TEMPLATE_EXCEL_SENSITIVE,
} from 'app/features/template/template/model/template-excel-columns';
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { TemplateRepository } from 'app/features/template/template/repository/template-repository.service';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { Template } from 'app/features/template/template/model/template.model';
import { take, map } from 'rxjs';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'template-view-export-action',
  standalone: false,
  templateUrl: './template-view-export-action.component.html',
})
export class TemplateViewExportActionComponent extends BaseExportAction<Template> {
  protected readonly scope = 'template/template';
  protected readonly repository = inject(TemplateRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ExportDefinition<Template> = {
    name: 'template.template',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: TEMPLATE_EXCEL_COLUMNS,
    sensitive: TEMPLATE_EXCEL_SENSITIVE,
    references: {
      tenant: {
        names: (refs) =>
          this.tenantRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
